EMBEDDED_TEMPLATES = {'base.html': '<!DOCTYPE html>\n<html lang="en" data-section="home">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>{% block title %}{{ seo.page_title }}{% endblock %}</title>\n  <meta name="description" content="{% block description %}{{ seo.meta_description }}{% endblock %}">\n  <meta name="keywords" content="Nagasrinivas Govvala, fresher software developer, Python, Django, AI, Machine Learning, Hyderabad">\n  <meta name="author" content="Nagasrinivas Govvala">\n  <meta name="robots" content="index, follow">\n\n  <!-- Open Graph -->\n  <meta property="og:title" content="{% block og_title %}{{ seo.page_title }}{% endblock %}">\n  <meta property="og:description" content="{% block og_desc %}{{ seo.meta_description }}{% endblock %}">\n  <meta property="og:type" content="website">\n  <meta property="og:url" content="{{ request.build_absolute_uri }}">\n  {% if seo.og_image %}<meta property="og:image" content="{{ seo.og_image.url }}">{% endif %}\n\n  <!-- Twitter -->\n  <meta name="twitter:card" content="summary_large_image">\n  <meta name="twitter:title" content="{% block tw_title %}{{ seo.page_title }}{% endblock %}">\n  <meta name="twitter:description" content="{{ seo.meta_description }}">\n\n  <!-- Canonical -->\n  {% if seo.canonical_url %}\n  <link rel="canonical" href="{{ seo.canonical_url }}">\n  {% endif %}\n\n  <!-- Favicon -->\n  {% load static %}\n  <link rel="icon" href="{% static \'favicon.svg\' %}" type="image/svg+xml">\n  <meta name="csrf-token" content="{{ csrf_token }}">\n\n  <!-- Fonts -->\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;700&display=swap" rel="stylesheet">\n\n  <!-- CSS -->\n  {% load static %}\n  <link rel="stylesheet" href="{% static \'css/base.css\' %}">\n  <link rel="stylesheet" href="{% static \'css/nav.css\' %}">\n  {% block extra_css %}{% endblock %}\n\n  <!-- Structured Data -->\n  <script type="application/ld+json">\n  {\n    "@context": "https://schema.org",\n    "@type": "Person",\n    "name": "{{ profile.full_name }}",\n    "jobTitle": "{{ profile.title }}",\n    "url": "{{ request.build_absolute_uri }}",\n    "sameAs": [\n      "{{ github_url }}",\n      "{{ linkedin_url }}"\n    ],\n    "address": {\n      "@type": "PostalAddress",\n      "addressLocality": "Hyderabad",\n      "addressRegion": "Telangana",\n      "addressCountry": "IN"\n    }\n  }\n  </script>\n</head>\n<body>\n\n{% include \'partials/nav.html\' %}\n\n<main id="main-content">\n  {% block content %}{% endblock %}\n</main>\n\n{% include \'partials/footer.html\' %}\n{% include \'partials/chatbot.html\' %}\n{% include \'partials/music_player.html\' %}\n\n<!-- Scripts -->\n<script>\n  window.CSRF_TOKEN = \'{{ csrf_token }}\';\n</script>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r134/three.min.js" crossorigin="anonymous" referrerpolicy="no-referrer"></script>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js" crossorigin="anonymous" referrerpolicy="no-referrer"></script>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js" crossorigin="anonymous" referrerpolicy="no-referrer"></script>\n<script src="{% static \'js/modules/utils.js\' %}"></script>\n<script src="{% static \'js/modules/nav.js\' %}"></script>\n<script src="{% static \'js/modules/animations.js\' %}"></script>\n<script src="{% static \'js/modules/music.js\' %}"></script>\n<script src="{% static \'js/modules/chatbot.js\' %}"></script>\n{% block extra_js %}{% endblock %}\n</body>\n</html>\n', 'core/home.html': '{% extends \'base.html\' %}\n{% load static portfolio_tags %}\n\n{% block extra_css %}\n<link rel="stylesheet" href="{% static \'css/home.css\' %}">\n<link rel="stylesheet" href="{% static \'css/chatbot.css\' %}">\n{% endblock %}\n\n{% block content %}\n\n<!-- ====== HERO ====== -->\n<section id="home" class="hero-section">\n  <canvas id="hero-canvas" aria-hidden="true"></canvas>\n\n  <div class="hero-content container">\n    <div class="hero-hud reveal">\n      <span class="hero-hud-dot"></span>\n      <span class="text-mono" style="font-size:0.65rem;letter-spacing:0.18em;color:var(--purple-400);">SYSTEM ONLINE · NAGASRINIVAS.GOVVALA · SOFTWARE DEVELOPER</span>\n    </div>\n\n    <h1 class="hero-name" id="hero-name" aria-label="Nagasrinivas Govvala"></h1>\n\n    <div class="hero-role-wrap" aria-live="polite">\n      <span class="hero-role-prefix text-mono" style="color:var(--text-muted);font-size:1rem;">// </span>\n      <span class="hero-role" id="hero-role" aria-label="Current role"></span>\n      <span class="hero-cursor" aria-hidden="true">|</span>\n    </div>\n\n    <p class="hero-tagline reveal reveal-delay-2">\n      Building practical software with Python, Django, AI and modern web technologies.\n    </p>\n\n    <div class="hero-cta reveal reveal-delay-3">\n      <a href="#projects" class="btn btn-primary">Explore My Work</a>\n      {% if profile.resume %}\n      <a href="{{ profile.resume.url }}" class="btn btn-outline" download aria-label="Download resume PDF">Download Resume</a>\n      {% endif %}\n    </div>\n\n    <div class="hero-links reveal reveal-delay-4">\n      {% if github_url %}<a href="{{ github_url }}" target="_blank" rel="noopener noreferrer" class="hero-social-link" aria-label="GitHub">GitHub</a>{% endif %}\n      {% if linkedin_url %}<a href="{{ linkedin_url }}" target="_blank" rel="noopener noreferrer" class="hero-social-link" aria-label="LinkedIn">LinkedIn</a>{% endif %}\n      {% if contact_email %}<a href="mailto:{{ contact_email }}" class="hero-social-link" aria-label="Email">Email</a>{% endif %}\n    </div>\n  </div>\n\n  <a href="#about" class="scroll-indicator" aria-label="Scroll down">\n    <span class="scroll-line"></span>\n    <span class="text-mono" style="font-size:0.6rem;letter-spacing:0.15em;color:var(--text-muted);">SCROLL</span>\n  </a>\n</section>\n\n\n<!-- ====== ABOUT ====== -->\n<section id="about">\n  <div class="container">\n    <div class="section-header reveal">\n      <span class="section-label">01 — Identity</span>\n      <h2 class="section-title">Who I Am</h2>\n      <div class="separator"></div>\n    </div>\n\n    <div class="about-grid">\n      <div class="about-text reveal">\n        <p style="color:var(--text-secondary);font-size:1.05rem;line-height:1.8;margin-bottom:1.5rem;">\n          I\'m <strong style="color:var(--text-primary);">Nagasrinivas Govvala</strong> — a fresher looking for software developer role from Hyderabad, Telangana. I graduated with a B.Tech in Computer Science and Engineering in 2025.\n        </p>\n        <p style="color:var(--text-secondary);font-size:1.05rem;line-height:1.8;margin-bottom:1.5rem;">\n          My development journey has been defined not by years in industry, but by shipping real applications that solve actual problems. I build with <strong style="color:var(--purple-300);">Python and Django</strong> as my primary stack, experiment with machine learning and NLP, and create production-oriented websites.\n        </p>\n        <p style="color:var(--text-secondary);font-size:1.05rem;line-height:1.8;">\n          I use modern AI-assisted development workflows as collaborative tools. My approach: <em style="color:var(--purple-300);">"Build and learn by shipping real projects."</em>\n        </p>\n        {% if profile.available_for_work %}\n        <div style="margin-top:1.5rem;">\n          <span class="status-live">Available for opportunities</span>\n        </div>\n        {% endif %}\n      </div>\n\n      <div class="about-stats reveal reveal-delay-2">\n        <div class="stat-card glass-card" style="padding:1.5rem;text-align:center;">\n          <div style="font-family:var(--font-mono);font-size:2rem;font-weight:700;color:var(--purple-400);margin-bottom:0.5rem;">2025</div>\n          <div style="font-size:0.8rem;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.1em;">B.Tech Graduate</div>\n        </div>\n        <div class="stat-card glass-card" style="padding:1.5rem;text-align:center;">\n          <div style="font-family:var(--font-mono);font-size:2rem;font-weight:700;color:var(--purple-400);margin-bottom:0.5rem;">3+</div>\n          <div style="font-size:0.8rem;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.1em;">Major Projects</div>\n        </div>\n        <div class="stat-card glass-card" style="padding:1.5rem;text-align:center;">\n          <div style="font-family:var(--font-mono);font-size:1.2rem;font-weight:700;color:var(--purple-400);margin-bottom:0.5rem;">Python</div>\n          <div style="font-size:0.8rem;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.1em;">Primary Language</div>\n        </div>\n        <div class="stat-card glass-card" style="padding:1.5rem;text-align:center;">\n          <div style="font-family:var(--font-mono);font-size:1.2rem;font-weight:700;color:var(--purple-400);margin-bottom:0.5rem;">AI / ML</div>\n          <div style="font-size:0.8rem;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.1em;">Development Focus</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n\n<!-- ====== SKILLS ====== -->\n<section id="skills" style="background:rgba(10,10,18,0.5);">\n  <div class="container">\n    <div class="section-header reveal">\n      <span class="section-label">02 — Technology</span>\n      <h2 class="section-title">Technology System</h2>\n      <div class="separator"></div>\n      <p class="text-muted" style="max-width:500px;">The tools I build with, organized by domain.</p>\n    </div>\n\n    <div class="skills-grid reveal">\n      {% regroup technologies by get_category_display as tech_categories %}\n      {% for category in tech_categories %}\n      <div class="skill-category glass-card" style="padding:1.5rem;">\n        <h3 style="font-family:var(--font-mono);font-size:0.7rem;letter-spacing:0.15em;text-transform:uppercase;color:var(--purple-400);margin-bottom:1rem;">{{ category.grouper }}</h3>\n        <div class="tech-nodes">\n          {% for tech in category.list %}\n          <div class="tech-node" data-name="{{ tech.name }}" data-desc="{{ tech.description }}" data-project="{{ tech.related_project }}" tabindex="0" role="button" aria-label="{{ tech.name }}">\n            <span class="tech-node-icon">{% tech_logo tech.name tech.color 20 %}</span>\n            <span class="tech-node-name">{{ tech.name }}</span>\n          </div>\n          {% endfor %}\n        </div>\n      </div>\n      {% endfor %}\n    </div>\n\n    <!-- Tech tooltip -->\n    <div id="tech-tooltip" class="tech-tooltip" aria-live="polite" hidden>\n      <div class="tech-tooltip-name" id="tooltip-name"></div>\n      <div class="tech-tooltip-desc" id="tooltip-desc"></div>\n      <div class="tech-tooltip-project" id="tooltip-project"></div>\n    </div>\n  </div>\n</section>\n\n\n<!-- ====== PROJECTS ====== -->\n<section id="projects">\n  <div class="container">\n    <div class="section-header reveal">\n      <span class="section-label">03 — Work</span>\n      <h2 class="section-title">Projects I Actually Built</h2>\n      <div class="separator"></div>\n    </div>\n\n    <div class="projects-grid">\n      {% for project in featured_projects %}\n      <article class="project-card glass-card reveal" data-delay="{{ forloop.counter0 }}" data-url="{% url \'projects:detail\' project.slug %}" tabindex="0" role="link" aria-label="View {{ project.title }} case study">\n        <div class="project-media">\n          {% if project.thumbnail %}\n          <img\n            class="project-thumbnail"\n            src="{{ project.thumbnail.url }}"\n            alt="{{ project.title }} screenshot"\n            loading="lazy"\n          >\n          {% endif %}\n          {% if project.hover_gif %}\n          <img\n            class="project-gif"\n            data-src="{{ project.hover_gif.url }}"\n            alt="{{ project.title }} preview animation"\n            loading="lazy"\n            aria-hidden="true"\n          >\n          {% endif %}\n          <div class="project-overlay">\n            <span class="btn btn-primary" style="font-size:0.8rem;padding:0.5rem 1.15rem;pointer-events:none;">View Case Study →</span>\n          </div>\n        </div>\n\n        <div class="project-body">\n          <div style="display:flex;align-items:center;gap:0.75rem;margin-bottom:0.75rem;flex-wrap:wrap;">\n            <span class="status-live">{{ project.category }}</span>\n            <span style="font-family:var(--font-mono);font-size:0.65rem;color:var(--text-muted);">\n              {% if project.is_completed %}COMPLETED{% endif %}\n            </span>\n          </div>\n          <h3 style="font-size:1.3rem;margin-bottom:0.5rem;">{{ project.title }}</h3>\n          <p style="color:var(--text-secondary);font-size:0.9rem;line-height:1.6;margin-bottom:1rem;">{{ project.short_description }}</p>\n\n          <div class="tech-badges" style="display:flex;flex-wrap:wrap;gap:0.4rem;margin-bottom:1.25rem;">\n            {% for tech in project.technologies.all|slice:":6" %}\n            <span class="tech-badge">{{ tech.name }}</span>\n            {% endfor %}\n          </div>\n\n          <div style="display:flex;flex-wrap:wrap;gap:0.5rem;align-items:center;">\n            {% if project.github_url %}\n            <a href="{{ project.github_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-ghost" style="font-size:0.75rem;padding:0.4rem 0.9rem;" aria-label="{{ project.title }} GitHub">GitHub</a>\n            {% endif %}\n            {% if project.live_url %}\n            <a href="{{ project.live_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-outline" style="font-size:0.75rem;padding:0.4rem 0.9rem;" aria-label="{{ project.title }} live demo">Live Demo</a>\n            {% endif %}\n            <a href="{% url \'projects:detail\' project.slug %}" class="btn btn-ghost" style="font-size:0.75rem;padding:0.4rem 0.9rem;" aria-label="{{ project.title }} case study">Case Study →</a>\n          </div>\n        </div>\n      </article>\n      {% empty %}\n      <p class="text-muted">Projects coming soon.</p>\n      {% endfor %}\n    </div>\n  </div>\n</section>\n\n\n<!-- ====== FUTURE PROJECTS ====== -->\n{% if future_projects %}\n<section id="future" style="background:rgba(10,10,18,0.5);">\n  <div class="container">\n    <div class="section-header reveal">\n      <span class="section-label">04 — Next</span>\n      <h2 class="section-title">Projects in Development</h2>\n      <div class="separator"></div>\n      <p class="text-muted">What I\'m building next. Not completed — in progress.</p>\n    </div>\n\n    <div class="future-grid">\n      {% for fp in future_projects %}\n      <article class="future-card glass-card reveal" data-delay="{{ forloop.counter0 }}">\n        {% if fp.thumbnail %}\n        <div class="future-card-img">\n          <img src="{{ fp.thumbnail.url }}" alt="{{ fp.title }}" loading="lazy">\n          <div class="future-card-overlay"></div>\n        </div>\n        {% else %}\n        <div class="future-card-placeholder">\n          <div class="future-placeholder-icon">◈</div>\n        </div>\n        {% endif %}\n\n        <div class="future-card-body">\n          <div style="display:flex;align-items:center;gap:0.75rem;margin-bottom:0.75rem;flex-wrap:wrap;">\n            <span class="status-dev">{{ fp.get_status_display }}</span>\n            <span style="font-family:var(--font-mono);font-size:0.6rem;color:var(--text-muted);letter-spacing:0.1em;">IN DEVELOPMENT</span>\n          </div>\n          <h3 style="font-size:1.1rem;margin-bottom:0.4rem;">{{ fp.title }}</h3>\n          <p style="color:var(--purple-300);font-size:0.85rem;margin-bottom:0.75rem;font-style:italic;">{{ fp.concept }}</p>\n          <p style="color:var(--text-secondary);font-size:0.875rem;line-height:1.6;margin-bottom:1rem;">{{ fp.description|truncatechars:120 }}</p>\n\n          {% if fp.technologies_planned %}\n          <div style="display:flex;flex-wrap:wrap;gap:0.35rem;margin-bottom:1rem;">\n            {% for tech in fp.get_technologies_list %}\n            <span class="tech-badge" style="opacity:0.6;">{{ tech }}</span>\n            {% endfor %}\n          </div>\n          {% endif %}\n\n          <a href="{% url \'projects:future_detail\' fp.slug %}" class="btn btn-outline" style="font-size:0.75rem;padding:0.4rem 0.9rem;">Explore Concept →</a>\n        </div>\n      </article>\n      {% endfor %}\n    </div>\n  </div>\n</section>\n{% endif %}\n\n\n<!-- ====== EDUCATION ====== -->\n<section id="education">\n  <div class="container">\n    <div class="section-header reveal">\n      <span class="section-label">05 — Background</span>\n      <h2 class="section-title">Education</h2>\n      <div class="separator"></div>\n    </div>\n\n    <div class="education-timeline">\n      {% for edu in educations %}\n      <div class="edu-node reveal" data-delay="{{ forloop.counter0 }}">\n        <div class="edu-connector" aria-hidden="true">\n          <div class="edu-dot"></div>\n          {% if not forloop.last %}<div class="edu-line"></div>{% endif %}\n        </div>\n        <div class="edu-card glass-card hud-corner">\n          <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:0.5rem;margin-bottom:0.75rem;">\n            <span class="section-label" style="font-size:0.65rem;">{{ edu.year }}</span>\n            <span style="font-family:var(--font-mono);font-size:0.75rem;color:var(--purple-400);">{{ edu.grade }}</span>\n          </div>\n          <h3 style="font-size:1.1rem;margin-bottom:0.25rem;">{{ edu.degree }}</h3>\n          <p style="color:var(--purple-300);font-size:0.9rem;margin-bottom:0.25rem;">{{ edu.field }}</p>\n          <p style="color:var(--text-secondary);font-size:0.875rem;">{{ edu.institution }}</p>\n        </div>\n      </div>\n      {% endfor %}\n\n      <!-- Experience entries -->\n      {% for exp in experiences %}\n      <div class="edu-node reveal" data-delay="{{ forloop.counter }}">\n        <div class="edu-connector" aria-hidden="true">\n          <div class="edu-dot" style="background:var(--neon-cyan);box-shadow:0 0 8px var(--neon-cyan);"></div>\n          {% if not forloop.last %}<div class="edu-line"></div>{% endif %}\n        </div>\n        <div class="edu-card glass-card hud-corner">\n          <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:0.5rem;margin-bottom:0.75rem;">\n            <span class="section-label" style="font-size:0.65rem;color:var(--neon-cyan);">{{ exp.get_exp_type_display }}</span>\n            <span style="font-family:var(--font-mono);font-size:0.65rem;color:var(--text-muted);">\n              {{ exp.start_date.year }}{% if exp.is_current %} — Present{% elif exp.end_date %} — {{ exp.end_date.year }}{% endif %}\n            </span>\n          </div>\n          <h3 style="font-size:1.1rem;margin-bottom:0.25rem;">{{ exp.title }}</h3>\n          <p style="color:var(--neon-cyan);font-size:0.9rem;margin-bottom:0.5rem;">{{ exp.organization }}</p>\n          <p style="color:var(--text-secondary);font-size:0.875rem;line-height:1.6;">{{ exp.description|truncatechars:200 }}</p>\n        </div>\n      </div>\n      {% endfor %}\n    </div>\n  </div>\n</section>\n\n\n<!-- ====== CONTACT ====== -->\n<section id="contact" style="background:rgba(10,10,18,0.5);">\n  <div class="container">\n    <div class="section-header reveal" style="text-align:center;">\n      <span class="section-label">06 — Connect</span>\n      <h2 class="section-title" style="font-size:clamp(2rem,5vw,4rem);">Let\'s Build Something Useful.</h2>\n      <p style="color:var(--text-secondary);max-width:550px;margin:0 auto 2rem;line-height:1.8;">\n        I\'m open to software development opportunities, collaborations and projects where I can solve real problems with technology.\n      </p>\n      <div style="display:flex;justify-content:center;gap:1rem;flex-wrap:wrap;margin-bottom:3rem;">\n        {% if github_url %}<a href="{{ github_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-outline">GitHub</a>{% endif %}\n        {% if linkedin_url %}<a href="{{ linkedin_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-outline">LinkedIn</a>{% endif %}\n        {% if contact_email %}<a href="mailto:{{ contact_email }}" class="btn btn-primary">Send Email</a>{% endif %}\n      </div>\n    </div>\n\n    <div class="contact-form-wrap reveal reveal-delay-2">\n      <div class="glass-card hud-corner" style="padding:2.5rem;max-width:640px;margin:0 auto;">\n        <h3 style="font-family:var(--font-mono);font-size:0.8rem;letter-spacing:0.15em;text-transform:uppercase;color:var(--purple-400);margin-bottom:1.5rem;">Send a Message</h3>\n        <form id="contact-form" novalidate>\n          {% csrf_token %}\n          <div class="form-group">\n            <label for="id_name" class="form-label">Name</label>\n            <input type="text" id="id_name" name="name" class="form-input" placeholder="Your Name" required maxlength="200" autocomplete="name">\n          </div>\n          <div class="form-group">\n            <label for="id_email" class="form-label">Email</label>\n            <input type="email" id="id_email" name="email" class="form-input" placeholder="your@email.com" required autocomplete="email">\n          </div>\n          <div class="form-group">\n            <label for="id_subject" class="form-label">Subject</label>\n            <input type="text" id="id_subject" name="subject" class="form-input" placeholder="Subject" required maxlength="300">\n          </div>\n          <div class="form-group">\n            <label for="id_message" class="form-label">Message</label>\n            <textarea id="id_message" name="message" class="form-input" rows="5" placeholder="Your message..." required style="resize:vertical;"></textarea>\n          </div>\n          <div id="contact-feedback" class="form-feedback" role="alert" aria-live="assertive"></div>\n          <button type="submit" class="btn btn-primary" id="contact-submit" style="width:100%;justify-content:center;margin-top:0.5rem;">\n            <span id="contact-btn-text">Send Message</span>\n          </button>\n        </form>\n      </div>\n    </div>\n  </div>\n</section>\n\n{% endblock %}\n\n{% block extra_js %}\n<script>\nwindow.HERO_ROLES = [{% for role in hero_roles %}"{{ role.role|escapejs }}"{% if not forloop.last %},{% endif %}{% endfor %}];\n</script>\n<script src="{% static \'js/hero3d.js\' %}"></script>\n<script src="{% static \'js/home.js\' %}"></script>\n{% endblock %}\n', 'partials/chatbot.html': '{% load static %}\n<!-- AI Chatbot Widget -->\n<div id="chatbot-container" aria-live="polite" aria-label="AI Assistant">\n  <!-- Floating button -->\n  <button id="chatbot-toggle" class="chatbot-fab" aria-label="Open AI assistant — Ask Srinivas AI" aria-expanded="false">\n    <span class="chatbot-fab-icon">◈</span>\n    <span class="chatbot-fab-label">Ask Srinivas AI</span>\n  </button>\n\n  <!-- Chat panel -->\n  <div id="chatbot-panel" class="chatbot-panel" role="dialog" aria-modal="true" aria-label="Ask Srinivas AI" hidden>\n    <div class="chatbot-header">\n      <div class="chatbot-identity">\n        <div class="chatbot-avatar">◈</div>\n        <div>\n          <div class="chatbot-name">Srinivas AI</div>\n          <div class="chatbot-status">Portfolio Intelligence Active</div>\n        </div>\n      </div>\n      <button class="chatbot-close" id="chatbot-close" aria-label="Close AI assistant">✕</button>\n    </div>\n\n    <div class="chatbot-messages" id="chatbot-messages" role="log" aria-live="polite">\n      <div class="chat-msg ai">\n        <div class="chat-bubble">Hi. I\'m Srinivas AI. Ask me about Nagasrinivas\'s projects, skills, education, technologies or development work.</div>\n      </div>\n      <div class="chat-suggestions">\n        <button class="suggestion-chip" data-msg="What projects has Nagasrinivas built?">Projects built</button>\n        <button class="suggestion-chip" data-msg="What technologies does he use?">Tech stack</button>\n        <button class="suggestion-chip" data-msg="Tell me about ResumeAI">ResumeAI</button>\n        <button class="suggestion-chip" data-msg="What is his educational background?">Education</button>\n      </div>\n    </div>\n\n    <form class="chatbot-input-area" id="chatbot-form" autocomplete="off">\n      {% csrf_token %}\n      <input\n        type="text"\n        id="chatbot-input"\n        class="chatbot-input"\n        placeholder="Ask about Nagasrinivas..."\n        maxlength="500"\n        aria-label="Your question"\n        autocomplete="off"\n      >\n      <button type="submit" class="chatbot-send" aria-label="Send message">\n        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M22 2L11 13"/><path d="M22 2L15 22 11 13 2 9l20-7z"/></svg>\n      </button>\n    </form>\n  </div>\n</div>\n', 'partials/footer.html': '{% load static %}\n<footer style="position:relative;z-index:1;border-top:1px solid var(--border-subtle);padding:3rem 0 2rem;">\n  <div class="container">\n    <div style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:1.5rem;margin-bottom:2rem;">\n      <div>\n        <div style="font-family:var(--font-mono);font-size:1.4rem;font-weight:700;color:#fff;margin-bottom:0.5rem;">{{ site.logo_text|default:"NG." }}</div>\n        <p style="color:var(--text-secondary);font-size:0.875rem;max-width:400px;">{{ site.tagline }}</p>\n      </div>\n      <div style="display:flex;gap:1rem;">\n        {% if github_url %}\n        <a href="{{ github_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-ghost" aria-label="GitHub profile" style="padding:0.5rem 1rem;">GitHub</a>\n        {% endif %}\n        {% if linkedin_url %}\n        <a href="{{ linkedin_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-ghost" aria-label="LinkedIn profile" style="padding:0.5rem 1rem;">LinkedIn</a>\n        {% endif %}\n        {% if contact_email %}\n        <a href="mailto:{{ contact_email }}" class="btn btn-ghost" aria-label="Send email" style="padding:0.5rem 1rem;">Email</a>\n        {% endif %}\n      </div>\n    </div>\n    <div style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:1rem;padding-top:1.5rem;border-top:1px solid var(--border-subtle);">\n      <p style="color:var(--text-muted);font-family:var(--font-mono);font-size:0.7rem;letter-spacing:0.08em;">\n        © 2025 NAGASRINIVAS GOVVALA · HYDERABAD, TELANGANA\n      </p>\n    </div>\n  </div>\n</footer>\n', 'partials/music_player.html': '<!-- Music Player (floating) -->\n<div id="music-player" class="music-player" aria-label="Ambient music player" hidden>\n  <div class="music-player-inner">\n    <div class="music-info">\n      <span class="music-now-playing" id="musicTrackName">No track</span>\n    </div>\n    <div class="music-controls">\n      <button id="musicPrevBtn" class="music-btn" aria-label="Previous track">‹</button>\n      <button id="musicPlayBtn" class="music-btn music-btn-main" aria-label="Play / Pause">▶</button>\n      <button id="musicNextBtn" class="music-btn" aria-label="Next track">›</button>\n    </div>\n    <input type="range" id="musicVolume" class="music-volume" min="0" max="1" step="0.05" value="0.4" aria-label="Volume">\n  </div>\n</div>\n', 'partials/nav.html': '{% load static %}\n<nav id="main-nav" role="navigation" aria-label="Main navigation">\n  <div class="container">\n    <div class="nav-inner">\n      <a href="/" class="nav-logo" aria-label="Nagasrinivas Govvala — Home">{{ site.logo_text|default:"NG." }}</a>\n\n      <ul class="nav-links" role="list">\n        <li><a href="/#about">About</a></li>\n        <li><a href="/#skills">Skills</a></li>\n        <li><a href="/#projects">Projects</a></li>\n        <li><a href="/#future">Future</a></li>\n        <li><a href="/#education">Education</a></li>\n        <li><a href="/#contact">Contact</a></li>\n      </ul>\n\n      <div class="nav-actions">\n        <button class="music-toggle" id="musicToggleNav" aria-label="Toggle ambient music" title="Toggle music">\n          ♪\n        </button>\n        <button class="ai-toggle" id="aiToggleNav" aria-label="Open AI assistant">\n          AI\n        </button>\n        <button class="hamburger" id="hamburger" aria-label="Open mobile menu" aria-expanded="false">\n          <span></span><span></span><span></span>\n        </button>\n      </div>\n    </div>\n  </div>\n</nav>\n\n<!-- Mobile menu -->\n<div class="mobile-menu" id="mobileMenu" aria-hidden="true">\n  <button class="mobile-menu-close" id="mobileMenuClose" aria-label="Close menu">✕</button>\n  <a href="/#about" class="mobile-nav-link">About</a>\n  <a href="/#skills" class="mobile-nav-link">Skills</a>\n  <a href="/#projects" class="mobile-nav-link">Projects</a>\n  <a href="/#future" class="mobile-nav-link">Future</a>\n  <a href="/#education" class="mobile-nav-link">Education</a>\n  <a href="/#contact" class="mobile-nav-link">Contact</a>\n</div>\n', 'projects/detail.html': '{% extends \'base.html\' %}\n{% load static %}\n\n{% block title %}{{ project.title }} | Nagasrinivas Govvala{% endblock %}\n{% block description %}{{ project.short_description }}{% endblock %}\n\n{% block extra_css %}\n<link rel="stylesheet" href="{% static \'css/project.css\' %}">\n{% endblock %}\n\n{% block content %}\n<!-- Project hero -->\n<section class="project-hero">\n  <div class="container">\n    <nav class="breadcrumb" aria-label="Breadcrumb">\n      <a href="/">Home</a>\n      <span aria-hidden="true"> / </span>\n      <a href="/#projects">Projects</a>\n      <span aria-hidden="true"> / </span>\n      <span>{{ project.title }}</span>\n    </nav>\n\n    <div class="project-hero-content">\n      <div style="display:flex;align-items:center;gap:0.75rem;margin-bottom:1rem;flex-wrap:wrap;">\n        <span class="status-live">{{ project.category }}</span>\n        <span style="font-family:var(--font-mono);font-size:0.65rem;color:var(--text-muted);letter-spacing:0.1em;">COMPLETED PROJECT</span>\n      </div>\n      <h1 style="font-size:clamp(2rem,6vw,4rem);margin-bottom:1rem;">{{ project.title }}</h1>\n      <p style="color:var(--text-secondary);font-size:1.1rem;max-width:650px;line-height:1.7;margin-bottom:2rem;">{{ project.short_description }}</p>\n\n      <div class="tech-badges" style="display:flex;flex-wrap:wrap;gap:0.4rem;margin-bottom:2rem;">\n        {% for tech in project.technologies.all %}\n        <span class="tech-badge">{{ tech.name }}</span>\n        {% endfor %}\n      </div>\n\n      <div style="display:flex;gap:0.75rem;flex-wrap:wrap;">\n        {% if project.github_url %}\n        <a href="{{ project.github_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-outline">GitHub →</a>\n        {% endif %}\n        {% if project.live_url %}\n        <a href="{{ project.live_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-primary">Live Demo →</a>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Sticky project nav -->\n<nav class="project-sticky-nav" id="project-sticky-nav" aria-label="Project sections">\n  <div class="container" style="display:flex;gap:0.25rem;overflow-x:auto;padding-bottom:0.5rem;">\n    {% if project.problem %}<a href="#overview" class="project-nav-link">Overview</a>{% endif %}\n    {% if project.features %}<a href="#features" class="project-nav-link">Features</a>{% endif %}\n    {% if project.architecture %}<a href="#architecture" class="project-nav-link">Architecture</a>{% endif %}\n    {% if project.screenshots.exists %}<a href="#screenshots" class="project-nav-link">Screenshots</a>{% endif %}\n    {% if project.challenges %}<a href="#challenges" class="project-nav-link">Challenges</a>{% endif %}\n  </div>\n</nav>\n\n<!-- Project body -->\n<div class="project-body-layout container">\n  <article class="project-content">\n\n    {% if project.hover_gif or project.thumbnail %}\n    <div class="project-showcase" id="overview">\n      {% if project.hover_gif %}\n      <img src="{{ project.hover_gif.url }}" alt="{{ project.title }} demo" class="project-main-img" loading="lazy">\n      {% elif project.thumbnail %}\n      <img src="{{ project.thumbnail.url }}" alt="{{ project.title }} screenshot" class="project-main-img" loading="lazy">\n      {% endif %}\n    </div>\n    {% endif %}\n\n    {% if project.problem %}\n    <section class="case-section">\n      <h2 class="case-section-title">The Problem</h2>\n      <p class="case-text">{{ project.problem }}</p>\n    </section>\n    {% endif %}\n\n    {% if project.solution %}\n    <section class="case-section">\n      <h2 class="case-section-title">The Solution</h2>\n      <p class="case-text">{{ project.solution }}</p>\n    </section>\n    {% endif %}\n\n    {% if project.features %}\n    <section class="case-section" id="features">\n      <h2 class="case-section-title">Key Features</h2>\n      <ul class="features-list">\n        {% for feature in project.features_list %}\n        <li>{{ feature }}</li>\n        {% endfor %}\n      </ul>\n    </section>\n    {% endif %}\n\n    {% if project.architecture %}\n    <section class="case-section" id="architecture">\n      <h2 class="case-section-title">Architecture</h2>\n      <div class="case-text">{{ project.architecture|linebreaksbr }}</div>\n    </section>\n    {% endif %}\n\n    {% if project.screenshots.exists %}\n    <section class="case-section" id="screenshots">\n      <h2 class="case-section-title">Screenshots</h2>\n      <div class="screenshots-grid">\n        {% for ss in project.screenshots.all %}\n        <figure class="screenshot-item">\n          <img src="{{ ss.image.url }}" alt="{{ ss.caption|default:project.title }}" loading="lazy">\n          {% if ss.caption %}<figcaption>{{ ss.caption }}</figcaption>{% endif %}\n        </figure>\n        {% endfor %}\n      </div>\n    </section>\n    {% endif %}\n\n    {% if project.challenges %}\n    <section class="case-section" id="challenges">\n      <h2 class="case-section-title">Challenges</h2>\n      <p class="case-text">{{ project.challenges }}</p>\n    </section>\n    {% endif %}\n\n    {% if project.learning %}\n    <section class="case-section">\n      <h2 class="case-section-title">What I Learned</h2>\n      <p class="case-text">{{ project.learning }}</p>\n    </section>\n    {% endif %}\n\n    {% if project.result %}\n    <section class="case-section">\n      <h2 class="case-section-title">Result</h2>\n      <p class="case-text">{{ project.result }}</p>\n    </section>\n    {% endif %}\n\n    <div class="case-cta">\n      {% if project.github_url %}\n      <a href="{{ project.github_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-outline">View on GitHub →</a>\n      {% endif %}\n      {% if project.live_url %}\n      <a href="{{ project.live_url }}" target="_blank" rel="noopener noreferrer" class="btn btn-primary">Live Demo →</a>\n      {% endif %}\n      <a href="/#projects" class="btn btn-ghost">← Back to Projects</a>\n    </div>\n  </article>\n\n  <!-- Sidebar -->\n  <aside class="project-sidebar">\n    <div class="glass-card" style="padding:1.5rem;margin-bottom:1.25rem;">\n      <h3 class="sidebar-title">Tech Stack</h3>\n      <div style="display:flex;flex-direction:column;gap:0.5rem;">\n        {% for tech in project.technologies.all %}\n        <span style="font-size:0.875rem;color:var(--text-secondary);">{{ tech.name }}</span>\n        {% endfor %}\n      </div>\n    </div>\n\n    {% if related_projects %}\n    <div class="glass-card" style="padding:1.5rem;">\n      <h3 class="sidebar-title">Other Projects</h3>\n      <div style="display:flex;flex-direction:column;gap:0.75rem;">\n        {% for rp in related_projects %}\n        <a href="{% url \'projects:detail\' rp.slug %}" style="color:var(--text-secondary);font-size:0.875rem;transition:color 0.2s;">\n          {{ rp.title }} →\n        </a>\n        {% endfor %}\n      </div>\n    </div>\n    {% endif %}\n  </aside>\n</div>\n{% endblock %}\n\n{% block extra_js %}\n<script src="{% static \'js/project.js\' %}"></script>\n{% endblock %}\n', 'projects/future_detail.html': '{% extends \'base.html\' %}\n{% load static %}\n\n{% block title %}{{ project.title }} — In Development | Nagasrinivas Govvala{% endblock %}\n\n{% block extra_css %}\n<link rel="stylesheet" href="{% static \'css/project.css\' %}">\n<style>\n.future-construction {\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  padding: 6rem 1.5rem;\n  position: relative;\n  overflow: hidden;\n}\n.construction-bg {\n  position: absolute;\n  inset: 0;\n  background: radial-gradient(ellipse 70% 50% at 50% 50%, rgba(88,28,220,0.15) 0%, transparent 70%);\n  pointer-events: none;\n}\n.blueprint-lines {\n  position: absolute;\n  inset: 0;\n  background-image:\n    linear-gradient(rgba(92,28,220,0.06) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(92,28,220,0.06) 1px, transparent 1px);\n  background-size: 50px 50px;\n  animation: blueprint-scroll 20s linear infinite;\n}\n@keyframes blueprint-scroll {\n  from { transform: translateY(0); }\n  to { transform: translateY(50px); }\n}\n.construction-content {\n  position: relative;\n  z-index: 2;\n  max-width: 600px;\n}\n.construction-icon {\n  font-size: 4rem;\n  margin-bottom: 2rem;\n  animation: construction-spin 8s linear infinite;\n  display: inline-block;\n}\n@keyframes construction-spin {\n  from { transform: rotate(0deg); }\n  to { transform: rotate(360deg); }\n}\n.construction-log {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  color: var(--purple-400);\n  margin: 2rem 0;\n  text-align: left;\n  background: rgba(10,10,18,0.8);\n  border: 1px solid var(--border-subtle);\n  border-radius: var(--radius-md);\n  padding: 1.25rem 1.5rem;\n  letter-spacing: 0.06em;\n}\n.log-line {\n  margin: 0.4rem 0;\n  opacity: 0;\n  animation: log-appear 0.5s ease forwards;\n}\n.log-line:nth-child(1) { animation-delay: 0.3s; }\n.log-line:nth-child(2) { animation-delay: 0.8s; }\n.log-line:nth-child(3) { animation-delay: 1.4s; }\n.log-line:nth-child(4) { animation-delay: 2.0s; }\n.log-line:nth-child(5) { animation-delay: 2.6s; }\n@keyframes log-appear {\n  from { opacity: 0; transform: translateX(-10px); }\n  to { opacity: 1; transform: translateX(0); }\n}\n.progress-bar-wrap {\n  margin: 1.5rem 0;\n  height: 3px;\n  background: rgba(139,92,246,0.15);\n  border-radius: 2px;\n  overflow: hidden;\n}\n.progress-bar-fill {\n  height: 100%;\n  background: linear-gradient(90deg, var(--purple-600), var(--neon-cyan));\n  border-radius: 2px;\n  animation: scanning 2s ease-in-out infinite alternate;\n}\n@keyframes scanning {\n  from { width: 10%; margin-left: 0; }\n  to { width: 40%; margin-left: 60%; }\n}\n</style>\n{% endblock %}\n\n{% block content %}\n<section class="future-construction">\n  <div class="blueprint-lines" aria-hidden="true"></div>\n  <div class="construction-bg" aria-hidden="true"></div>\n\n  <div class="construction-content">\n    <div class="construction-icon" aria-hidden="true">◈</div>\n\n    <div style="display:flex;justify-content:center;margin-bottom:1rem;">\n      <span class="status-dev">{{ project.get_status_display }}</span>\n    </div>\n\n    <h1 style="font-size:clamp(1.8rem,5vw,3rem);margin-bottom:1rem;">{{ project.title }}</h1>\n    <p style="color:var(--purple-300);font-size:1rem;margin-bottom:0.75rem;font-style:italic;">{{ project.concept }}</p>\n    <p style="color:var(--text-secondary);font-size:0.95rem;line-height:1.7;margin-bottom:2rem;">{{ project.description }}</p>\n\n    <div class="construction-log" role="status" aria-label="Development status log">\n      <div class="log-line">▸ SYSTEM INITIALIZING...</div>\n      <div class="log-line">▸ ARCHITECTURE UNDER DEVELOPMENT...</div>\n      <div class="log-line">▸ MODULES BEING DESIGNED...</div>\n      <div class="log-line">▸ CORE SYSTEMS: RESEARCHING...</div>\n      <div class="log-line">▸ STATUS: COMING SOON</div>\n    </div>\n\n    <div class="progress-bar-wrap" aria-hidden="true">\n      <div class="progress-bar-fill"></div>\n    </div>\n\n    <p style="color:var(--text-secondary);font-size:0.9rem;margin-bottom:2rem;line-height:1.7;">\n      I\'m currently developing this project.<br>Check back later.\n    </p>\n\n    {% if project.technologies_planned %}\n    <div style="margin-bottom:2rem;">\n      <p style="font-family:var(--font-mono);font-size:0.65rem;letter-spacing:0.1em;color:var(--text-muted);margin-bottom:0.75rem;text-transform:uppercase;">Planned Stack</p>\n      <div style="display:flex;flex-wrap:wrap;gap:0.4rem;justify-content:center;">\n        {% for tech in project.get_technologies_list %}\n        <span class="tech-badge" style="opacity:0.6;">{{ tech }}</span>\n        {% endfor %}\n      </div>\n    </div>\n    {% endif %}\n\n    <a href="/#projects" class="btn btn-outline">← Back to Projects</a>\n  </div>\n</section>\n{% endblock %}\n'}

class EmbeddedTemplateLoader(BaseLoader):
    def get_template_sources(self, template_name):
        yield Origin(
            name=f'embedded:{template_name}',
            template_name=template_name,
            loader=self,
        )

    def get_contents(self, origin):
        # 1. Try reading directly from filesystem if available
        base_dir = Path(__file__).resolve().parent.parent
        candidates = [
            base_dir / 'templates' / origin.template_name,
            base_dir / 'core' / 'templates' / origin.template_name,
            base_dir / 'projects' / 'templates' / origin.template_name,
            base_dir / 'portfolio' / 'templates' / origin.template_name,
            Path('/var/task/templates') / origin.template_name,
            Path('/var/task/core/templates') / origin.template_name,
            Path('/var/task/portfolio/templates') / origin.template_name,
            Path('/var/task/projects/templates') / origin.template_name,
        ]
        for c in candidates:
            if c.is_file():
                try:
                    return c.read_text(encoding='utf-8')
                except Exception:
                    pass

        # 2. Match exact template name in embedded dictionary
        t_name = origin.template_name
        if t_name in EMBEDDED_TEMPLATES:
            return EMBEDDED_TEMPLATES[t_name]

        # 3. Match without or with prefix
        for k, v in EMBEDDED_TEMPLATES.items():
            if k.endswith(t_name) or t_name.endswith(k):
                return v

        raise TemplateDoesNotExist(origin.template_name)
